<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#06100a">
<title>JADIEL MUSIC</title>
<style>
:root{--bg:#050806;--p:#0b130e;--p2:#101a14;--line:#1c2b21;--txt:#f4fff7;--muted:#8da195;--g:#2be66f}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#174725,#050806 55%);color:var(--txt);font-family:system-ui,-apple-system,Segoe UI,Arial}.top{height:72px;padding:0 22px;display:flex;align-items:center;gap:18px;border-bottom:1px solid var(--line);background:#07100de8;backdrop-filter:blur(18px);position:sticky;top:0;z-index:5}.logo{font-weight:900;white-space:nowrap}.logo b{display:inline-grid;place-items:center;width:35px;height:35px;border-radius:11px;background:var(--g);color:#031008;margin-right:9px}.search{max-width:700px;flex:1;margin:auto}.search input{width:100%;height:44px;border-radius:14px;border:1px solid var(--line);background:#0b1510;color:white;padding:0 17px;outline:0}.search input:focus{border-color:var(--g)}main{max-width:1400px;margin:auto;padding:32px 24px 130px}.hero{display:flex;justify-content:space-between;gap:20px;align-items:end}.hero h1{font-size:clamp(34px,5vw,58px);margin:0}.hero p{color:var(--muted)}button{cursor:pointer}.btn{border:1px solid var(--line);background:#101b15;color:white;border-radius:12px;padding:11px 15px;font-weight:700}.green{background:var(--g);color:#031008;border:0}.drop{margin:28px 0;padding:22px;border:1px dashed #31563d;border-radius:16px;background:#09130e;display:flex;justify-content:space-between;align-items:center;gap:15px}.drop small{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(175px,1fr));gap:16px}.card{background:linear-gradient(160deg,#111b15,#09100c);border:1px solid var(--line);border-radius:17px;padding:11px;position:relative;overflow:hidden}.cover{aspect-ratio:1;background:#122018;border-radius:12px;overflow:hidden;position:relative}.cover img{width:100%;height:100%;object-fit:cover}.play{position:absolute;right:10px;bottom:10px;width:43px;height:43px;border:0;border-radius:50%;background:var(--g);font-weight:900}.card h3{font-size:14px;margin:11px 2px 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card p{font-size:12px;color:var(--muted);margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fav{position:absolute;right:14px;top:14px;border:0;border-radius:50%;background:#06100dcc;color:white;width:32px;height:32px}.empty{padding:60px 20px;border:1px dashed #28402f;border-radius:18px;text-align:center;color:var(--muted)}.player{position:fixed;bottom:0;left:0;right:0;height:100px;background:#07100cf5;border-top:1px solid var(--line);backdrop-filter:blur(20px);display:grid;grid-template-columns:1fr 2fr 1fr;align-items:center;gap:20px;padding:12px 24px;z-index:10}.now{display:flex;align-items:center;gap:12px;min-width:0}.now img{width:58px;height:58px;border-radius:10px;object-fit:cover;background:#132018}.now b,.now span{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.now span{font-size:12px;color:var(--muted);margin-top:4px}.controls{text-align:center}.buttons{display:flex;justify-content:center;align-items:center;gap:10px}.icon,.big{border:0;background:transparent;color:#b9c9bf}.big{width:43px;height:43px;border-radius:50%;background:white;color:#07100c}.progress{display:flex;gap:8px;align-items:center;color:#718479;font-size:10px}.progress input{flex:1;accent-color:var(--g)}.vol{text-align:right}.vol input{accent-color:var(--g);width:110px}.toast{position:fixed;right:20px;bottom:115px;padding:12px 15px;border-radius:12px;background:#102118;border:1px solid #28543a;opacity:0;transition:.2s;z-index:20}.toast.on{opacity:1}@media(max-width:800px){.top{padding:0 12px}.logo{font-size:0}.logo b{margin:0}.hero{display:block}.player{grid-template-columns:1fr auto;height:92px;padding:9px 12px}.controls{grid-column:2}.vol{display:none}.now img{width:48px;height:48px}.grid{grid-template-columns:repeat(2,1fr)}main{padding:22px 14px 120px}.drop{align-items:flex-start;flex-direction:column}}
</style>
</head>
<body>
<header class="top"><div class="logo"><b>♪</b>JADIEL MUSIC</div><div class="search"><input id="q" placeholder="Buscar música, artista ou álbum..."></div><button class="btn green" id="go">Buscar</button></header>
<main>
<section class="hero"><div><h1>Ouça do seu jeito.</h1><p>Busque músicas, reproduza prévias e toque seus próprios arquivos.</p></div><div><button class="btn" id="url">▶ URL de áudio</button> <button class="btn green" id="add">＋ Música local</button></div></section>
<div class="drop" id="drop"><div><b>Arraste músicas para cá</b><br><small>MP3, WAV, OGG, M4A e outros formatos suportados pelo navegador.</small></div><button class="btn" id="pick">Selecionar arquivos</button></div>
<input id="files" type="file" accept="audio/*" multiple hidden>
<h2 id="heading">Descobrir músicas</h2><div id="grid" class="grid"></div>
</main>
<div class="player"><div class="now"><img id="art"><div><b id="nt">Nenhuma música</b><span id="na">Escolha uma música</span></div></div><div class="controls"><div class="buttons"><button class="icon" id="prev">◀</button><button class="big" id="play">▶</button><button class="icon" id="next">▶</button></div><div class="progress"><span id="ct">0:00</span><input id="bar" type="range" min="0" max="100" value="0"><span id="dt">0:00</span></div></div><div class="vol">🔊 <input id="volume" type="range" min="0" max="1" step=".01" value=".8"></div></div>
<div class="toast" id="toast"></div><audio id="audio"></audio>
<script>
const audio=document.getElementById('audio'),grid=document.getElementById('grid'),q=document.getElementById('q'),toastEl=document.getElementById('toast');
let list=[],pos=-1,repeat=false,favs=JSON.parse(localStorage.getItem('jm_favs')||'[]');
function toast(s){toastEl.textContent=s;toastEl.classList.add('on');clearTimeout(window.tt);window.tt=setTimeout(function(){toastEl.classList.remove('on')},2400)}
function esc(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function time(s){return isFinite(s)?Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0'):'0:00'}
function render(){if(!list.length){grid.innerHTML='<div class="empty" style="grid-column:1/-1">Pesquise uma música ou adicione arquivos do seu dispositivo.</div>';return}grid.innerHTML=list.map(function(x,i){return '<article class="card"><div class="cover"><img src="'+esc(x.art||'')+'" onerror="this.style.display=\'none\'"><button class="play" onclick="playAt('+i+')">▶</button></div><button class="fav" onclick="fav(\''+esc(x.id)+'\')">'+(favs.indexOf(x.id)>=0?'♥':'♡')+'</button><h3>'+esc(x.title)+'</h3><p>'+esc(x.artist)+'</p></article>'}).join('')}
window.playAt=function(i){if(!list[i])return;pos=i;var x=list[i];audio.src=x.src;document.getElementById('nt').textContent=x.title;document.getElementById('na').textContent=x.artist;document.getElementById('art').src=x.art||'';audio.play().catch(function(){toast('Toque em ▶ para iniciar')})}
window.fav=function(id){var i=favs.indexOf(id);if(i>=0)favs.splice(i,1);else favs.push(id);localStorage.setItem('jm_favs',JSON.stringify(favs));render()}
function next(){if(list.length)playAt((pos+1)%list.length)}function prev(){if(list.length)playAt((pos-1+list.length)%list.length)}
document.getElementById('play').onclick=function(){if(!audio.src){if(list.length)playAt(0);else toast('Pesquise ou adicione uma música');return}audio.paused?audio.play():audio.pause()};
document.getElementById('next').onclick=next;document.getElementById('prev').onclick=prev;
document.getElementById('volume').oninput=function(e){audio.volume=e.target.value};audio.volume=.8;
audio.onplay=function(){document.getElementById('play').textContent='❚❚'};audio.onpause=function(){document.getElementById('play').textContent='▶'};audio.onended=function(){next()};
audio.ontimeupdate=function(){if(audio.duration){document.getElementById('bar').value=audio.currentTime/audio.duration*100;document.getElementById('ct').textContent=time(audio.currentTime);document.getElementById('dt').textContent=time(audio.duration)}};
document.getElementById('bar').oninput=function(e){if(audio.duration)audio.currentTime=e.target.value/100*audio.duration};
async function searchMusic(){var term=q.value.trim();if(!term)return;document.getElementById('heading').textContent='Resultados para: '+term;grid.innerHTML='<div class="empty" style="grid-column:1/-1">Buscando…</div>';try{var r=await fetch('https://itunes.apple.com/search?term='+encodeURIComponent(term)+'&media=music&entity=song&limit=40');var d=await r.json();list=d.results.filter(function(x){return x.previewUrl}).map(function(x){return {id:String(x.trackId),title:x.trackName,artist:x.artistName,art:(x.artworkUrl100||'').replace('100x100','600x600'),src:x.previewUrl}});render();if(!list.length)toast('Nenhuma prévia encontrada')}catch(e){grid.innerHTML='<div class="empty" style="grid-column:1/-1">A busca não respondeu. Tente novamente ou use suas músicas locais.</div>';toast('Erro na busca')}}
document.getElementById('go').onclick=searchMusic;q.onkeydown=function(e){if(e.key==='Enter')searchMusic()};
function addFiles(fs){Array.from(fs).filter(function(f){return f.type.indexOf('audio/')===0}).forEach(function(f){list.push({id:'local-'+Date.now()+Math.random(),title:f.name.replace(/\.[^.]+$/,''),artist:'Meu dispositivo',art:'',src:URL.createObjectURL(f)})});document.getElementById('heading').textContent='Minhas músicas';render();toast('Música adicionada')}
var files=document.getElementById('files');document.getElementById('add').onclick=function(){files.click()};document.getElementById('pick').onclick=function(){files.click()};files.onchange=function(e){addFiles(e.target.files)};
var drop=document.getElementById('drop');drop.ondragover=function(e){e.preventDefault()};drop.ondrop=function(e){e.preventDefault();addFiles(e.dataTransfer.files)};
document.getElementById('url').onclick=function(){var u=prompt('Cole uma URL direta de um arquivo de áudio:');if(!u)return;try{new URL(u);list.push({id:'url-'+Date.now(),title:'Áudio por URL',artist:'URL externa',art:'',src:u});document.getElementById('heading').textContent='Minha fila';render();playAt(list.length-1)}catch(e){toast('URL inválida')}};
render();
</script>
</body></html>